function annualNewsMarkup(context){const events=yearEvents[year()]||[];return `<section class="daily-news annual-news" data-context="${context}"><header class="daily-news-head"><span>▤ ${year()} 年大事记</span><small>YEAR IN REVIEW</small></header><div class="news-controls"><button data-year-step="-1">‹ 上一年</button><span>全年回顾 · 不按月日截断</span><button data-year-step="1">下一年 ›</button></div><div class="news-feed">${events.length?events.map(n=>`<article class="news-item"><time>${n[0]}</time><a href="${n[2]||CHRONICLE}" target="_blank" rel="noopener noreferrer">${n[1]}</a><small>${n[3]||'中国政府网'}</small></article>`).join(''):'<div class="news-empty">这个年份的大事记正在整理中。</div>'}</div><footer class="news-foot">编辑精选，非完整年鉴；标题为简要概括，点击核对原始资料。资料链接可能是后来的回顾文章。</footer></section>`}
document.addEventListener('click',e=>{const el=e.target.closest('[data-year-step]');if(el){const y=Number(year())+Number(el.dataset.yearStep);applyDate(`${y}${date.slice(4)}`)}});
